from taf.sbts.oam.coam.admin.schemas.procedure.ccm_uplink import CCMUplink


class CCMUplinkPrach(CCMUplink):
    def __init__(self, nrcell_rdn, nrarfcn_ul, nrarfcn_dl, reporting_time_interval, beam_pattern_id, performance_test_type,
                 ru_mode, phys_cell_id, prach_configuration_index, pfa_target_prach_id, receiving_slot=None,
                 expectation_slot=None, preamble_index=None, accepted_timing_error=None,
                 constant_offset=None, delay_pattern_single_step_duration=None, prach_root_sequence_index=None,
                 zero_correlation_zone_config=None, prach_sequence_type=None, act_prach_format_c2_with_scs=None, act_high_speed_cell=None,
                 digital_output_enable=None):

        super(CCMUplinkPrach, self).__init__(nrcell_rdn=nrcell_rdn,
                                             nrarfcn_ul=nrarfcn_ul,
                                             nrarfcn_dl=nrarfcn_dl,
                                             reporting_time_interval=reporting_time_interval,
                                             beam_pattern_id=beam_pattern_id,
                                             performance_test_type=performance_test_type,
                                             ru_mode=ru_mode,
                                             phys_cell_id=phys_cell_id)

        self.act_high_speed_cell = self.validate_param('actHighSpeedCell',
                                                       act_high_speed_cell,
                                                       (act_high_speed_cell is None
                                                        or act_high_speed_cell in (True, False)))
        self.digital_output_enable = self.validate_param('digitalOutputEnable',
                                                         digital_output_enable,
                                                         digital_output_enable in (True, False))

        self.prach_params = {"receivingSlot": self.validate_param('receivingSlot',
                                                                  receiving_slot,
                                                                  (0 <= receiving_slot <= 1023)),
                             "expectationSlot": self.validate_param('expectationSlot',
                                                                    expectation_slot,
                                                                    (0 <= expectation_slot <= 1023)),
                             "preambleIndex": self.validate_param('preambleIndex',
                                                                  preamble_index,
                                                                  (0 <= preamble_index <= 63)),
                             "acceptedTimingError": self.validate_param('acceptedTimingError',
                                                                        accepted_timing_error,
                                                                        (0 <= accepted_timing_error <= 999999)),
                             "constantOffset": self.validate_param('constantOffset',
                                                                   constant_offset,
                                                                   (0 <= constant_offset <= 999999)),
                             "delayPatternSingleStepDuration": self.validate_param(
                                 'delayPatternSingleStepDuration',
                                 delay_pattern_single_step_duration,
                                 (0 <= delay_pattern_single_step_duration <= 1000)),
                             "prachConfigurationIndex": self.validate_param('prachConfigurationIndex',
                                                                            prach_configuration_index,
                                                                            (0 <= prach_configuration_index <= 255)),
                             "pfaTargetPrachId": self.validate_param('pfaTargetPrachId',
                                                                     pfa_target_prach_id,
                                                                     (pfa_target_prach_id in ("P_None", "P_01", "P_001",
                                                                                              "P_0005", "P_0001",
                                                                                              "P_005", "P_05", "P_10"))),
                             "prachRootSequenceIndex": self.validate_param('prachRootSequenceIndex',
                                                                           prach_root_sequence_index,
                                                                           (0 <= prach_root_sequence_index <= 837)),
                             "zeroCorrelationZoneConfig": self.validate_param('zeroCorrelationZoneConfig',
                                                                              zero_correlation_zone_config,
                                                                              (0 <= zero_correlation_zone_config <= 15)),
                             "prachSequenceType": self.validate_param('prachSequenceType',
                                                                      prach_sequence_type,
                                                                      (prach_sequence_type in ("Unrestricted", "RestrictedTypeA"))),
                             "actPrachC2Scs15kHzTddFr1": self.validate_param('actPrachC2Scs15kHzTddFr1',
                                                                             act_prach_format_c2_with_scs,
                                                                             act_prach_format_c2_with_scs in (True, False))
                             }

    @classmethod
    def from_response_dict(cls, response_dict):
        def _get_prach_param(parameter):
            return response_dict['params']['prachParams'][parameter]

        nrcell_rdn = response_dict['nrcell_rDN']
        nrarfcn_ul = response_dict['params']['nrarfcnUl'] if 'nrarfcnUl' in response_dict['params'] else None
        nrarfcn_dl = response_dict['params']['nrarfcnDl'] if 'nrarfcnDl' in response_dict['params'] else None
        reporting_time_interval = response_dict['params']['reportingTimeInterval']
        beam_pattern_id = response_dict['params']['beamPatternId']
        performance_test_type = response_dict['params']['performanceTestType']
        ru_mode = response_dict['params']['ruMode']
        phys_cell_id = response_dict['params']['physCellId']
        act_high_speed_cell = response_dict['params']['actHighSpeedCell']
        digital_output_enable = response_dict['params']['digitalOutputEnable']

        prach_params = {"receivingSlot": _get_prach_param('receivingSlot'),
                        "expectationSlot": _get_prach_param('expectationSlot'),
                        "preambleIndex": _get_prach_param('preambleIndex'),
                        "prachRootSequenceIndex": _get_prach_param('prachRootSequenceIndex'),
                        "zeroCorrelationZoneConfig": _get_prach_param('zeroCorrelationZoneConfig'),
                        "acceptedTimingError": _get_prach_param('acceptedTimingError'),
                        "constantOffset": _get_prach_param('constantOffset'),
                        "delayPatternSingleStepDuration": _get_prach_param('delayPatternSingleStepDuration'),
                        "prachConfigurationIndex": _get_prach_param('prachConfigurationIndex'),
                        "pfaTargetPrachId": _get_prach_param('pfaTargetPrachId'),
                        "prachSequenceType": _get_prach_param('prachSequenceType'),
                        "actPrachC2Scs15kHzTddFr1": _get_prach_param('actPrachC2Scs15kHzTddFr1')}

        return cls(nrcell_rdn=nrcell_rdn, nrarfcn_ul=nrarfcn_ul,
                   nrarfcn_dl=nrarfcn_dl,
                   reporting_time_interval=reporting_time_interval,
                   beam_pattern_id=beam_pattern_id,
                   performance_test_type=performance_test_type,
                   ru_mode=ru_mode,
                   phys_cell_id=phys_cell_id,
                   act_high_speed_cell=act_high_speed_cell,
                   digital_output_enable=digital_output_enable,
                   receiving_slot=prach_params['receivingSlot'],
                   expectation_slot=prach_params['expectationSlot'],
                   preamble_index=prach_params['preambleIndex'],
                   prach_root_sequence_index=prach_params['prachRootSequenceIndex'],
                   zero_correlation_zone_config=prach_params['zeroCorrelationZoneConfig'],
                   accepted_timing_error=prach_params['acceptedTimingError'],
                   constant_offset=prach_params['constantOffset'],
                   delay_pattern_single_step_duration=prach_params['delayPatternSingleStepDuration'],
                   prach_configuration_index=prach_params['prachConfigurationIndex'],
                   pfa_target_prach_id=prach_params['pfaTargetPrachId'],
                   prach_sequence_type=prach_params['prachSequenceType'],
                   act_prach_format_c2_with_scs=prach_params['actPrachC2Scs15kHzTddFr1'])

    def as_dict(self):
        attributes = {'nrcell_rDN': self.nrcell_rdn,
                      'params': {'nrarfcnUl': self.nrarfcn_ul,
                                 'nrarfcnDl': self.nrarfcn_dl,
                                 'reportingTimeInterval': self.reporting_time_interval,
                                 'beamPatternId': self.beam_pattern_id,
                                 'performanceTestType': self.performance_test_type,
                                 'ruMode': self.ru_mode,
                                 'physCellId': self.phys_cell_id,
                                 'actHighSpeedCell': self.act_high_speed_cell,
                                 'digitalOutputEnable': self.digital_output_enable
                                 }
                      }
        attributes['params'] = self._remove_empty_params(attributes['params'])
        self.prach_params = self._remove_empty_params(self.prach_params)
        attributes['params']['prachParams'] = self.prach_params

        return attributes

    @staticmethod
    def _remove_empty_params(params):
        return {k: v for k, v in params.items() if v is not None}
